// Begrenzter ausdrücklich abgeglichener Scope; begin/read initialisieren nichts.
// Belegreferenzen kommen vom Aufrufer und sind kein Befugnisnachweis.
export function initializeMaterialLedger({ ledgerPath, shopDomain, ownerIds, baselineEvidenceReference, persistenceEvidenceReference, initializationConfirmed, now }) {
  assert(initializationConfirmed === true && shopDomain === 'luxestyle.ch', 'Ausdrückliche LuxeStyle-Initialisierung erforderlich');
  assert(Array.isArray(ownerIds) && ownerIds.length > 0 && ownerIds.every(product) && new Set(ownerIds).size === ownerIds.length, 'Ausdrücklicher eindeutiger Produkt-Geltungsbereich erforderlich');
  assert(nonempty(baselineEvidenceReference) && nonempty(persistenceEvidenceReference), 'Belegreferenzen für Abdeckung und Persistenz erforderlich');
  return locked(ledgerPath, old => {
    assert(old === null, 'Vorhandenes Ledger darf nicht erneut initialisiert werden');
    const d = { version: VERSION, field: FIELD, scope: { shopDomain, ownerIds: [...ownerIds].sort(), baselineEvidenceReference, persistenceEvidenceReference, establishedAt: nowISO(now) }, entries: {} };
    checkpoint(ledgerPath, d); return { decision: 'initialized_limited_scope', scope: structuredClone(d.scope) };
  }, true);
}

// Keine Standardfrist: Die dokumentierte Projektregel muss separat vorliegen.
// Der Hash bindet übergebene Quellbytes; deren sachliche Richtigkeit bleibt separat zu prüfen.
export function checkSourceFreshness({ source, policy, now }) {
  if (!policy || !nonempty(policy.id) || !nonempty(policy.reference) || !Number.isSafeInteger(policy.maxAgeMs) || policy.maxAgeMs <= 0) return { ok: false, reason: 'source_age_policy_unknown' };
  if (!source || !product(source.ownerId) || !nonempty(source.reference) || !digest(source.sha256) || !(typeof source.bytes === 'string' || Buffer.isBuffer(source.bytes)) || hash(source.bytes) !== source.sha256) return { ok: false, reason: 'source_binding_unknown' };
  if (!nonempty(source.checkedAt)) return { ok: false, reason: 'source_timestamp_unknown' };
  let at, checked;
  try { at = nowISO(now); checked = nowISO(source.checkedAt); }
  catch { return { ok: false, reason: 'source_timestamp_unknown' }; }
  const age = Date.parse(at) - Date.parse(checked);
  if (age < 0) return { ok: false, reason: 'source_timestamp_future' };
  if (age > policy.maxAgeMs) return { ok: false, reason: 'source_stale', ageMs: age };
  return { ok: true, ownerId: source.ownerId, sourceSha256: source.sha256, sourceReference: source.reference, checkedAt: checked, policyId: policy.id, policyReference: policy.reference, maxAgeMs: policy.maxAgeMs };
}

function boundBatch(planBytes, batch) {
  assert(typeof planBytes === 'string' || Buffer.isBuffer(planBytes), 'Exakte Planbytes erforderlich');
  assert(Buffer.byteLength(planBytes) > 0 && Buffer.byteLength(planBytes) <= 8 * 1024 * 1024, 'Plan muss begrenzt und nicht leer sein');
  const rows = String(planBytes).split('\n').filter(Boolean).map(s => JSON.parse(s));
  assert(rows.every(x => product(x.id)) && new Set(rows.map(x => x.id)).size === rows.length, 'Plan-IDs ungültig oder doppelt');
  assert(Array.isArray(batch) && batch.length > 0 && batch.length <= 25 && new Set(batch.map(x => x.id)).size === batch.length, 'Stapel muss 1–25 eindeutige Produkte enthalten');
  const indexed = new Map(rows.map(x => [x.id, x]));
  for (const p of batch) {
    assert(indexed.has(p.id) && JSON.stringify(indexed.get(p.id)) === JSON.stringify(p), 'Stapel entspricht nicht dem exakt gelesenen Inhalt dieses Plans');
    assert(nonempty(p.wert) && Object.hasOwn(p, 'vorher') && (p.vorher === null || (sameKeys(p.vorher, ['value', 'type']) && typeof p.vorher.value === 'string' && p.vorher.type === FIELD.type)), 'Exakter Vorwert mit Typ oder null erforderlich');
