}

export function beginMaterialBatch({ ledgerPath, shopDomain, planBytes, batch, runId, sourceEvidence, sourceAgePolicy, now }) {
  assert(shopDomain === 'luxestyle.ch' && nonempty(runId), 'Ausdrückliche LuxeStyle- und Laufidentität erforderlich');
  const at = nowISO(now), bound = boundBatch(planBytes, batch), ownerIds = bound.items.map(i => i.ownerId);
  assert(Array.isArray(sourceEvidence) && sourceEvidence.length === ownerIds.length && new Set(sourceEvidence.map(s => s.ownerId)).size === ownerIds.length && sourceEvidence.every(s => ownerIds.includes(s.ownerId)), 'Vollständige eindeutige Quellenbelege erforderlich');
  const sources = sourceEvidence.map(source => checkSourceFreshness({ source, policy: sourceAgePolicy, now: at }));
  assert(sources.every(s => s.ok), 'Quellenfrische blockiert: ' + sources.filter(s => !s.ok).map(s => s.reason).join(','));
  for (const i of bound.items) {
    const s = sources.find(x => x.ownerId === i.ownerId), p = i.sourceEvidence;
    assert(s.sourceSha256 === p.sha256 && s.sourceReference === p.reference && s.checkedAt === p.checkedAt, 'Quelle ist nicht an die Planzeile gebunden');
  }
  return locked(ledgerPath, d => {
    assert(ownerIds.every(id => d.scope.ownerIds.includes(id)), 'Stapel ausserhalb des abgeglichenen Geltungsbereichs');
    // Jeden früheren Anspruch erhalten; auch ein neuer Planpfad oder Hash verdeckt ihn nicht.
    const overlap = Object.entries(d.entries).find(([, e]) => e.ownerIds.some(id => ownerIds.includes(id)));
    if (overlap) return { decision: 'existing_no_new_write', key: overlap[0], entry: structuredClone(overlap[1]) };
    const key = jsonHash([bound.planSha256, ownerIds]);
    const entry = { ...bound, ownerIds, runId, claimToken: randomUUID(), state: 'inflight', revision: 0, sources, startedAt: at, updatedAt: at, history: [{ state: 'inflight', at }] };
    checkEntry(key, entry); // Nur Einträge speichern, die derselbe Leser vollständig akzeptiert.
    d.entries[key] = entry; checkpoint(ledgerPath, d);
    return { decision: 'claimed_once', key, entry: structuredClone(entry) };
  });
}

export function finishMaterialBatch({ ledgerPath, key, claimToken, expectedRevision, state, readbacks, userErrors, reason, now }) {
  assert(digest(key) && nonempty(claimToken) && Number.isSafeInteger(expectedRevision) && expectedRevision >= 0, 'Exakter Anspruch und Revision erforderlich');
  assert(['confirmed', 'rejected', 'unknown', 'conflict'].includes(state), 'Kein Übergang für erneutes Senden vorhanden');
  const at = nowISO(now);
  return locked(ledgerPath, d => {
    const e = d.entries[key]; assert(e && e.claimToken === claimToken && e.revision === expectedRevision, 'Fehlender, veralteter oder falscher Anspruch');
    assert(['inflight', 'unknown', 'conflict'].includes(e.state), 'Endzustand darf nicht verändert oder erneut gesendet werden');
    assert(Date.parse(at) >= Date.parse(e.updatedAt), 'Beobachtung darf dem Kontrollpunkt nicht vorausgehen');
    let observation;
    if (state === 'confirmed') {
      assert(Array.isArray(readbacks) && readbacks.length === e.items.length && new Set(readbacks.map(r => r.ownerId)).size === e.items.length, 'Vollständige eindeutige Rücklesungen mit Typ erforderlich');
      observation = e.items.map(i => {
        const r = readbacks.find(x => x.ownerId === i.ownerId);
        assert(r && r.value === i.value && r.type === i.type && nonempty(r.checkedAt), 'Wert, Typ oder Produkt stimmt nicht überein');
        const checkedAt = nowISO(r.checkedAt); assert(Date.parse(checkedAt) >= Date.parse(e.updatedAt) && Date.parse(checkedAt) <= Date.parse(at), 'Frischer Rücklesezeitpunkt erforderlich');
        return { ownerId: i.ownerId, value: r.value, type: r.type, checkedAt };
      });
    } else if (state === 'rejected') {
      assert(e.state === 'inflight' && Array.isArray(userErrors) && userErrors.length > 0 && userErrors.every(x => nonempty(x?.message)), 'Definitive atomare metafieldsSet-userErrors erforderlich');
      observation = userErrors.map(x => ({ message: x.message, ...(nonempty(x.code) ? { code: x.code } : {}) }));
    } else {
      assert(nonempty(reason), 'Grund für unbekanntes Ergebnis oder Konflikt erforderlich'); observation = { reason };
    }
    e.state = state; e.revision++; e.updatedAt = at; e.observation = observation;
    e.history.push({ state, at, observation: structuredClone(observation) }); checkpoint(ledgerPath, d);
    return { decision: 'checkpointed', key, entry: structuredClone(e) };
  });
}

export function readMaterialLedger({ ledgerPath }) { return structuredClone(read(ledgerPath)); }

