import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createHash } from 'node:crypto';
const api = await import(process.env.MATERIAL_LEDGER_MODULE || './material_write_ledger.mjs');
const root = fs.mkdtempSync(path.join(process.env.MATERIAL_TEST_TMP || os.tmpdir(), 'material-bindung-'));
const hash = x => createHash('sha256').update(x).digest('hex');
const at = '2026-10-29T06:30:00.000Z', later = '2026-10-29T06:31:00.000Z';
const ownerId = 'gid://shopify/Product/1'; let seq = 0, ok = 0, bad = 0;
function setup() {
  const ledgerPath = path.join(root, `${seq++}.json`);
  api.initializeMaterialLedger({ ledgerPath, shopDomain: 'luxestyle.ch', ownerIds: [ownerId], initializationConfirmed: true, baselineEvidenceReference: 'synthetische Gegenprobe', persistenceEvidenceReference: 'lokales Testverzeichnis', now: at });
  const bytes = 'Quelle A: Material Baumwolle';
  const proof = { ownerId, sha256: hash(bytes), reference: 'Quelle A', checkedAt: at };
  const row = { id: ownerId, wert: 'Baumwolle', vorher: null, quelle: 'belegt-von-hand', sourceEvidence: proof };
  return { ledgerPath, shopDomain: 'luxestyle.ch', planBytes: JSON.stringify(row) + '\n', batch: [row], runId: 'Testlauf', sourceEvidence: [{ ...proof, bytes }], sourceAgePolicy: { id: 'Testfrist', reference: 'nur synthetisches Beispiel', maxAgeMs: 60000 }, now: at };
}
function rehash(file, change) { const d = JSON.parse(fs.readFileSync(file)); change(d.payload); d.sha256 = hash(JSON.stringify(d.payload)); fs.writeFileSync(file, JSON.stringify(d)); }
function claim(a) { return api.beginMaterialBatch(a); }
function rejectRead(change) { const a = setup(), c = claim(a); rehash(a.ledgerPath, d => change(d.entries[c.key])); assert.throws(() => api.readMaterialLedger({ ledgerPath: a.ledgerPath })); }
function test(name, fn) { try { fn(); ok++; console.log(`ok - ${name}`); } catch (e) { bad++; console.log(`FEHLER - ${name}: ${e.message}`); } }
try {
  test('Frische andere Quelle erfüllt den alten Materialplan nicht', () => { const a = setup(), bytes = 'Quelle B: Farbe blau'; a.sourceEvidence = [{ ownerId, bytes, sha256: hash(bytes), reference: 'Quelle B', checkedAt: at }]; assert.throws(() => claim(a)); });
  test('Fehlender Planbeleg blockiert', () => { const a = setup(); delete a.batch[0].sourceEvidence; a.planBytes = JSON.stringify(a.batch[0]) + '\n'; assert.throws(() => claim(a)); });
  test('Andere Referenz trotz gleichem Hash blockiert', () => { const a = setup(); a.sourceEvidence[0].reference = 'andere Herkunft'; assert.throws(() => claim(a)); });
  test('Andere Quellzeit trotz gleichem Inhalt blockiert', () => { const a = setup(); a.sourceEvidence[0].checkedAt = '2026-10-29T06:29:59.000Z'; assert.throws(() => claim(a)); });
  test('Zusatzfeld im Vorwert blockiert vor Speicherung', () => { const a = setup(), before = fs.readFileSync(a.ledgerPath); a.batch[0].vorher = { value: '', type: 'single_line_text_field', compareDigest: 'Zusatzfeld' }; a.planBytes = JSON.stringify(a.batch[0]) + '\n'; assert.throws(() => claim(a)); assert.deepEqual(fs.readFileSync(a.ledgerPath), before); });
  test('Neu gehashter falscher Endzustand ohne Historie blockiert', () => rejectRead(e => { e.state = 'confirmed'; e.history = []; delete e.sources; delete e.observation; }));
  test('Neu gehashte falsche Revisionszahl blockiert', () => rejectRead(e => { e.revision = 2; }));
  test('Neu gehashter falscher Quellenowner blockiert', () => rejectRead(e => { e.sources[0].ownerId = 'gid://shopify/Product/9'; }));
  test('Neu gehashte bestätigte Ausgabe mit falschem Typ blockiert', () => {
    const a = setup(), c = claim(a);
    api.finishMaterialBatch({ ledgerPath: a.ledgerPath, key: c.key, claimToken: c.entry.claimToken, expectedRevision: 0, state: 'confirmed', readbacks: [{ ownerId, value: 'Baumwolle', type: 'single_line_text_field', checkedAt: later }], now: later });
    rehash(a.ledgerPath, d => { const e = d.entries[c.key]; e.observation[0].type = 'multi_line_text_field'; if (e.history.at(-1).observation) e.history.at(-1).observation[0].type = 'multi_line_text_field'; });
    assert.throws(() => api.readMaterialLedger({ ledgerPath: a.ledgerPath }));
  });
  test('Neu gehashte unzulässige Historienfolge blockiert', () => rejectRead(e => { e.history[0].state = 'rejected'; }));
  test('Ursprünglicher Unknown-Grund bleibt nach Bestätigung erhalten', () => {
    const a = setup(), c = claim(a), why = 'Antwort nach Send verloren';
    const u = api.finishMaterialBatch({ ledgerPath: a.ledgerPath, key: c.key, claimToken: c.entry.claimToken, expectedRevision: 0, state: 'unknown', reason: why, now: later });
    const v = api.finishMaterialBatch({ ledgerPath: a.ledgerPath, key: c.key, claimToken: c.entry.claimToken, expectedRevision: u.entry.revision, state: 'confirmed', readbacks: [{ ownerId, value: 'Baumwolle', type: 'single_line_text_field', checkedAt: later }], now: later });
    assert.equal(api.readMaterialLedger({ ledgerPath: a.ledgerPath }).entries[c.key].history[1].observation.reason, why);
    assert.equal(v.entry.state, 'confirmed');
  });
  console.log(`${ok} ok, ${bad} Fehler`); if (bad) process.exitCode = 1;
} finally { fs.rmSync(root, { recursive: true, force: true }); }

// Nur Testdaten unter dem expliziten Fixture-Verzeichnis; keine Produktionsfreigabe.
import {readFileSync,writeFileSync,existsSync,copyFileSync} from 'node:fs';
import {join,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {initializeMaterialLedger} from './material_write_ledger.mjs';

export function materialFixtureBelege(dir) {
  copyFileSync(join(dirname(fileURLToPath(import.meta.url)),'material_write_ledger.mjs'),join(dir,'automation/lib/material_write_ledger.mjs'));
  const lines=readFileSync(join(dir,'roh.jsonl'),'utf8').split('\n').filter(Boolean);
  const rows=lines.map(JSON.parse),manualPath=join(dir,'dropship/material_belege.json');
  const manual=existsSync(manualPath)?readFileSync(manualPath,'utf8'):null,belege=manual?JSON.parse(manual):{};
  const date=join(dir,'fixture-source-time.txt');
  if(!existsSync(date))writeFileSync(date,new Date().toISOString());
  const checkedAt=readFileSync(date,'utf8');
  const sources=rows.map((p,i)=>{
    const cjPath=join(dir,'cache',p.handle+'.json'),cj=existsSync(cjPath)?readFileSync(cjPath,'utf8'):null;
    const bytes=JSON.stringify({productJsonl:lines[i],cjJson:cj,manualEvidenceJson:belege[p.handle]?manual:null});
    return {ownerId:p.id,sha256:createHash('sha256').update(bytes).digest('hex'),reference:'synthetische-fixture:'+p.id,checkedAt};
  });
  const ledgerPath=join(dir,'fixture-ledger.json'),evidencePath=join(dir,'fixture-evidence.json');
  if(!existsSync(ledgerPath))initializeMaterialLedger({ledgerPath,shopDomain:'luxestyle.ch',ownerIds:rows.map(p=>p.id),baselineEvidenceReference:'synthetischer begrenzter Testbestand',persistenceEvidenceReference:'lokales Testverzeichnis, keine Dauerhaftigkeitsbehauptung',initializationConfirmed:true});
  writeFileSync(evidencePath,JSON.stringify({sources,sourceAgePolicy:{id:'fixture-only-1h',reference:'explizite synthetische Testregel, keine Projekteinstellung',maxAgeMs:3600000}}));
  return {MATERIAL_WRITE_LEDGER:ledgerPath,MATERIAL_WRITE_EVIDENCE:evidencePath};
}
